// Примечание: точный API @jinx-ui/react мне недоступен — ниже использованы
// предполагаемые имена (Drawer/Menu/MenuItem/Divider) и пропсы
// (placement, open/onClose, tone="danger"). Сверьтесь с документацией пакета
// и при расхождении переименуйте компоненты/пропсы — логика не изменится.
import { useCallback, useState } from 'react';
import { Button, Divider, Drawer, Menu, MenuItem } from '@jinx-ui/react';

export type NavKey = 'projects' | 'team' | 'settings' | 'logout';

interface AppNavDrawerProps {
  onNavigate: (key: NavKey) => void;
}

const ITEMS: ReadonlyArray<{ key: NavKey; label: string }> = [
  { key: 'projects', label: 'Проекты' },
  { key: 'team', label: 'Команда' },
  { key: 'settings', label: 'Настройки' },
];

function AppNavDrawer({ onNavigate }: AppNavDrawerProps) {
  const [open, setOpen] = useState(false);

  const close = useCallback(() => setOpen(false), []);

  const select = useCallback(
    (key: NavKey) => {
      onNavigate(key);
      setOpen(false);
    },
    [onNavigate],
  );

  return (
    <>
      <Button onClick={() => setOpen(true)} aria-haspopup="menu" aria-expanded={open}>
        Меню
      </Button>

      <Drawer open={open} onClose={close} placement="left" title="Меню">
        <Menu aria-label="Основная навигация" style={{ padding: 'var(--jx-space-2)' }}>
          {ITEMS.map(({ key, label }) => (
            <MenuItem key={key} onClick={() => select(key)}>
              {label}
            </MenuItem>
          ))}

          <Divider style={{ marginBlock: 'var(--jx-space-2)' }} />

          <MenuItem tone="danger" onClick={() => select('logout')}>
            Выйти
          </MenuItem>
        </Menu>
      </Drawer>
    </>
  );
}

export default AppNavDrawer;

